src/rules/__tests__/no-context-generic-t.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'
import { noContextGenericTag } from '../no-context-generic-tag.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

ruleTester.run('no-context-generic-tag', noContextGenericTag, {
  valid: [
    {
      name: 'Should_AllowContextTag_When_UsedCorrectly',
      code: `
        import { Context } from 'effect'
        interface Database { readonly query: (sql: string) => unknown }
        const Database = Context.Tag('@app/Database')<Database, Database>()
      `,
    },
    {
      name: 'Should_AllowContextTag_When_ContextImportIsAliased',
      code: `
        import { Context as Ctx } from 'effect'
        interface Cache { readonly get: (key: string) => unknown }
        const Cache = Ctx.Tag('@app/Cache')<Cache, Cache>()
      `,
    },
    {
      name: 'Should_AllowClassExtendTag_When_UsingContextTagNotGenericTag',
      code: `
        import { Context } from 'effect'
        interface MyService { readonly value: string }
        class MyService extends Context.Tag('my-service')<MyService, MyService>() {}
      `,
    },
    {
      name: 'Should_AllowDestructuredTag_When_UsingTagNotGenericTag',
      code: `
        import { Context } from 'effect'
        const { Tag } = Context
        const MyTag = Tag('my-tag')<string, string>()
      `,
    },
    {
      name: 'Should_IgnoreGenericTag_When_ContextNotImportedFromEffect',
      code: `
        import { Effect, Layer } from 'effect'
        import { Context } from 'other-library'
        const tag = Context.GenericTag<string>('tag')
      `,
    },
    {
      name: 'Should_AllowContextMethods_When_CallingEmptyOrMake',
      code: `
        import { Context } from 'effect'
        const ctx = Context.empty()
      `,
    },
    {
      name: 'Should_AllowGenericTag_When_ImportedFromDifferentPackage',
      code: `
        import { GenericTag } from 'other-library'
        const MyTag = GenericTag<number>('my-tag')
      `,
    },
    {
      name: 'Should_AllowContext_When_SourceIsNotEffectModule',
      code: `
        import { Context } from 'react'
        const result = Context.Consumer
      `,
    },
    {
      name: 'Should_AllowNamespaceImport_When_UsingEffectNamespace',
      code: `
        import * as Effect from 'effect'
        const MyTag = Effect.Context.Tag('@app/MyTag')<string, string>()
      `,
    },
    {
      name: 'Should_AllowComputedProperty_When_AccessingDynamicKey',
      code: `
        import { Context } from 'effect'
        const key = 'GenericTag'
        const tag = Context[key]
      `,
    },
    {
      name: 'Should_AllowFunctionReturn_When_AccessingGenericTagDynamically',
      code: `
        import { Context } from 'effect'
        function getContext() { return Context }
        const tag = getContext().GenericTag
      `,
    },
    {
      name: 'Should_AllowClassExtend_When_ContextTagDirectCall',
      code: `
        import { Context } from 'effect'
        class MyService extends Context.Tag('my-service') {}
      `,
    },
    {
      name: 'Should_AllowClassExtend_When_DirectFunctionCall',
      code: `
        function makeTag(id: string) { return class {} }
        class MyService extends makeTag('my-service') {}
      `,
    },
    {
      name: 'Should_IgnoreDefaultImport_When_ImportingFromEffect',
      code: `
        import Context from 'effect'
        const tag = Context.GenericTag
      `,
    },
    {
      name: 'Should_AllowGenericTag_When_NonContextNamedImportFromEffect',
      code: `
        import { Effect } from 'effect'
        const tag = Effect.GenericTag
      `,
    },
    {
      name: 'Should_AllowTypeReference_When_UsingContextTag',
      code: `
        import { Context } from 'effect'
        type MyTag = Context.Tag<string, string>
      `,
    },
  ],
  invalid: [
    {
      name: 'Should_ReportViolation_When_AccessingContextGenericTag',
      code: `
        import { Context } from 'effect'
        const tag = Context.GenericTag
      `,
      errors: [{
        messageId: 'banned',
        data: {
          name: 'Context.GenericTag',
          expected: 'Context.Tag',
          actual: 'Context.GenericTag',
          fix: 'Replace with Context.Tag from effect',
        },
      }],
    },
    {
      name: 'Should_ReportViolation_When_AccessingGenericTagViaAliasedContext',
      code: `
        import { Context as Ctx } from 'effect'
        const tag = Ctx.GenericTag
      `,
      errors: [{ messageId: 'banned' }],
    },
    {
      name: 'Should_ReportViolation_When_CallingGenericTagWithTypeParameter',
      code: `
        import { Context } from 'effect'
        const Port = Context.GenericTag<number>("PORT")
      `,
      errors: [{ messageId: 'banned' }],
    },
    {
      name: 'Should_ReportViolation_When_UsingGenericTagWithComplexType',
      code: `
        import { Context } from 'effect'
        interface Logger { log: (msg: string) => void }
        const Logger = Context.GenericTag<Logger>("@services/Logger")
      `,
      errors: [{ messageId: 'banned' }],
    },
    {
      name: 'Should_ReportViolation_When_GenericTagUsedAsTypeAnnotation',
      code: `
        import { Context } from 'effect'
        function createTag(): GenericTag<string> {
          return Context.GenericTag<string>('tag')
        }
      `,
      errors: [
        { messageId: 'banned' },
        { messageId: 'banned' },
      ],
    },
    {
      name: 'Should_ReportViolation_When_GenericTagUsedInInterface',
      code: `
        import { Context } from 'effect'
        interface Service {
          tag: GenericTag<string>
        }
      `,
      errors: [{ messageId: 'banned' }],
    },
    {
      name: 'Should_ReportViolation_When_GenericTagUsedInClassProperty',
      code: `
        import { Context } from 'effect'
        class Container {
          tag: GenericTag<string>
        }
      `,
      errors: [{ messageId: 'banned' }],
    },
    {
      name: 'Should_ReportViolation_When_ClassExtendsContextGenericTag',
      code: `
        import { Context } from 'effect'
        class MyService extends Context.GenericTag<string>('my-service') {}
      `,
      errors: [
        { messageId: 'banned' },
        { messageId: 'banned' },
      ],
    },
    {
      name: 'Should_ReportViolation_When_ClassExtendsDestructuredGenericTag',
      code: `
        import { Context } from 'effect'
        const { GenericTag } = Context
        class MyService2 extends GenericTag<string>('service2') {}
      `,
      errors: [{ messageId: 'banned' }],
    },
    {
      name: 'Should_ReportMultipleViolations_When_GenericTagUsedMultipleTimes',
      code: `
        import { Context } from 'effect'
        const Tag1 = Context.GenericTag<string>('tag1')
        const Tag2 = Context.GenericTag<number>('tag2')
      `,
      errors: [{ messageId: 'banned' }, { messageId: 'banned' }],
    },
  ],
})

src/rules/__tests__/no-native-setinterva.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noNativeSetIntervalInEffect } from '../no-native-setinterval-in-effect.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const setIntervalError = {
  messageId: 'forbiddenSetInterval' as const,
  data: { expected: 'Effect.repeat with Schedule' },
}

const clearIntervalError = {
  messageId: 'forbiddenClearInterval' as const,
  data: { expected: 'Effect.fiberId + Fiber.interrupt' },
}

ruleTester.run('no-native-setinterval-in-effect', noNativeSetIntervalInEffect, {
  valid: [
    // No effect import — setInterval is allowed
    {
      name: 'allows setInterval without effect import',
      code: `
        setInterval(() => {}, 1000)
      `,
    },
    {
      name: 'allows clearInterval without effect import',
      code: `
        clearInterval(timerId)
      `,
    },
    // Effect imported but no interval usage
    {
      name: 'allows code with effect import but no interval usage',
      code: `
        import { Effect } from 'effect'
        const x = Effect.succeed(42)
      `,
    },
    // Non-effect import does not trigger
    {
      name: 'allows setInterval with non-effect import',
      code: `
        import { something } from 'other-lib'
        setInterval(() => {}, 1000)
      `,
    },
    // setTimeout is not banned
    {
      name: 'allows setTimeout with effect import',
      code: `
        import { Effect } from 'effect'
        setTimeout(() => {}, 1000)
      `,
    },
    // Other function calls
    {
      name: 'allows other function calls with effect import',
      code: `
        import { Effect } from 'effect'
        console.log('hello')
        Math.random()
      `,
    },
    // Variable alias that is NOT interval — must not false-positive
    {
      name: 'allows non-interval variable alias called in effect context',
      code: `
        import { Effect } from 'effect'
        const doStuff = () => {}
        doStuff()
      `,
    },
  ],
  invalid: [
    // Direct setInterval
    {
      name: 'detects setInterval() with effect import',
      code: `
        import { Effect } from 'effect'
        setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // Direct clearInterval
    {
      name: 'detects clearInterval() with effect import',
      code: `
        import { Effect } from 'effect'
        clearInterval(timerId)
      `,
      errors: [clearIntervalError],
    },
    // effect/ sub-path import
    {
      name: 'detects setInterval with effect/ sub-path import',
      code: `
        import { Schedule } from 'effect/Schedule'
        setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // @effect/ scoped import
    {
      name: 'detects setInterval with @effect/ scoped import',
      code: `
        import { Schema } from '@effect/schema'
        setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // globalThis.setInterval
    {
      name: 'detects globalThis.setInterval() with effect import',
      code: `
        import { Effect } from 'effect'
        globalThis.setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // window.setInterval
    {
      name: 'detects window.setInterval() with effect import',
      code: `
        import { Effect } from 'effect'
        window.setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // self.setInterval
    {
      name: 'detects self.setInterval() with effect import',
      code: `
        import { Effect } from 'effect'
        self.setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // globalThis.clearInterval
    {
      name: 'detects globalThis.clearInterval() with effect import',
      code: `
        import { Effect } from 'effect'
        globalThis.clearInterval(timerId)
      `,
      errors: [clearIntervalError],
    },
    // Bracket access: globalThis['setInterval']
    {
      name: 'detects globalThis["setInterval"]() with effect import',
      code: `
        import { Effect } from 'effect'
        globalThis['setInterval'](() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // Bracket access: window['clearInterval']
    {
      name: 'detects window["clearInterval"]() with effect import',
      code: `
        import { Effect } from 'effect'
        window['clearInterval'](timerId)
      `,
      errors: [clearIntervalError],
    },
    // Aliased setInterval (assignment is not a call, so only alias call reports)
    {
      name: 'detects aliased setInterval with effect import',
      code: `
        import { Effect } from 'effect'
        const myInterval = setInterval
        myInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // Aliased clearInterval
    {
      name: 'detects aliased clearInterval with effect import',
      code: `
        import { Effect } from 'effect'
        const myClear = clearInterval
        myClear(timerId)
      `,
      errors: [clearIntervalError],
    },
    // Aliased from globalThis member
    {
      name: 'detects alias from globalThis.setInterval',
      code: `
        import { Effect } from 'effect'
        const si = globalThis.setInterval
        si(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
    // Both setInterval and clearInterval in same file
    {
      name: 'detects both setInterval and clearInterval',
      code: `
        import { Effect } from 'effect'
        const id = setInterval(() => {}, 1000)
        clearInterval(id)
      `,
      errors: [setIntervalError, clearIntervalError],
    },
    // Namespace import triggers
    {
      name: 'detects setInterval with namespace import from effect',
      code: `
        import * as E from 'effect'
        setInterval(() => {}, 1000)
      `,
      errors: [setIntervalError],
    },
  ],
})

src/rules/__tests__/no-manual-tag-proper.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noManualTagProperty } from '../no-manual-tag-property.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const defaultExpected = 'Schema.TaggedClass or Schema.TaggedError from effect (Schema as S from "effect")'
const defaultFix =
  "Replace manual _tag with class MyClass extends S.TaggedClass<MyClass>('TagName')('variantName', { ... }) {} for variants, or class MyError extends S.TaggedError<MyError>()('MyError', { ... }) {} for errors"

const forbiddenError = (className: string) => ({
  messageId: 'forbidden' as const,
  data: {
    name: `class ${className} with manual _tag property`,
    expected: defaultExpected,
    actual: 'manual _tag property declaration',
    fix: defaultFix,
  },
})

ruleTester.run('no-manual-tag-property', noManualTagProperty, {
  valid: [
    // Classes without _tag
    {
      name: 'allows class without _tag property',
      code: `
        class Foo {
          name = 'foo'
        }
      `,
    },
    {
      name: 'allows class with non-_tag property',
      code: `
        class Foo {
          tag = 'foo'
          type = 'bar'
        }
      `,
    },
    // Effect TaggedClass / TaggedError patterns
    {
      name: 'allows Schema.TaggedClass pattern',
      code: `
        import { Schema as S } from 'effect'
        class MyClass extends S.TaggedClass<MyClass>()('MyClass', { value: S.Number }) {}
      `,
    },
    {
      name: 'allows Schema.TaggedError pattern',
      code: `
        import { Schema as S } from 'effect'
        class MyError extends S.TaggedError<MyError>()('MyError', { message: S.String }) {}
      `,
    },
    // Allowlisted classes
    {
      name: 'allows class in allow list',
      code: `
        class LegacyAction {
          _tag = 'LegacyAction'
        }
      `,
      options: [{ allow: ['LegacyAction'] }],
    },
    {
      name: 'allows class in allow list case-insensitive',
      code: `
        class LegacyAction {
          _tag = 'LegacyAction'
        }
      `,
      options: [{ allow: ['legacyaction'] }],
    },
    // Empty class
    {
      name: 'allows empty class',
      code: `class Empty {}`,
    },
    // Computed property that happens to be _tag string
    {
      name: 'allows computed _tag property',
      code: `
        const key = '_tag'
        class Foo {
          [key] = 'foo'
        }
      `,
    },
    // Class expression without _tag
    {
      name: 'allows class expression without _tag',
      code: `
        const Foo = class {
          name = 'foo'
        }
      `,
    },
  ],
  invalid: [
    // PropertyDefinition with _tag identifier
    {
      name: 'detects _tag property in class declaration',
      code: `
        class MyAction {
          _tag = 'MyAction'
        }
      `,
      errors: [forbiddenError('MyAction')],
    },
    // PropertyDefinition with _tag as string literal key
    {
      name: 'detects _tag as string literal property key',
      code: `
        class MyAction {
          '_tag' = 'MyAction'
        }
      `,
      errors: [forbiddenError('MyAction')],
    },
    // Class expression
    {
      name: 'detects _tag in class expression',
      code: `
        const MyAction = class MyAction {
          _tag = 'MyAction'
        }
      `,
      errors: [forbiddenError('MyAction')],
    },
    // Anonymous class expression
    {
      name: 'detects _tag in anonymous class expression',
      code: `
        const x = class {
          _tag = 'something'
        }
      `,
      errors: [forbiddenError('<anonymous>')],
    },
    // _tag with type annotation
    {
      name: 'detects _tag with type annotation',
      code: `
        class MyEvent {
          _tag: 'MyEvent' = 'MyEvent'
        }
      `,
      errors: [forbiddenError('MyEvent')],
    },
    // _tag as readonly
    {
      name: 'detects readonly _tag property',
      code: `
        class MyEvent {
          readonly _tag = 'MyEvent'
        }
      `,
      errors: [forbiddenError('MyEvent')],
    },
    // Custom expected/fix messages
    {
      name: 'uses custom expected and fix messages',
      code: `
        class MyAction {
          _tag = 'MyAction'
        }
      `,
      options: [{ expected: 'custom expected', fix: 'custom fix' }],
      errors: [{
        messageId: 'forbidden' as const,
        data: {
          name: 'class MyAction with manual _tag property',
          expected: 'custom expected',
          actual: 'manual _tag property declaration',
          fix: 'custom fix',
        },
      }],
    },
    // Multiple classes in one file
    {
      name: 'detects _tag in multiple classes',
      code: `
        class ActionA {
          _tag = 'ActionA'
        }
        class ActionB {
          _tag = 'ActionB'
        }
      `,
      errors: [
        forbiddenError('ActionA'),
        forbiddenError('ActionB'),
      ],
    },
    // Constructor with TSParameterProperty named _tag
    {
      name: 'detects _tag as constructor parameter property',
      code: `
        class MyAction {
          constructor(public _tag: string) {}
        }
      `,
      errors: [forbiddenError('MyAction')],
    },
    {
      name: 'detects _tag as constructor parameter property with default value',
      code: `
        class MyAction {
          constructor(public _tag = 'MyAction') {}
        }
      `,
      errors: [forbiddenError('MyAction')],
    },
    // Class with _tag and other properties
    {
      name: 'detects _tag among other properties',
      code: `
        class MyAction {
          name = 'action'
          _tag = 'MyAction'
          value = 42
        }
      `,
      errors: [forbiddenError('MyAction')],
    },
  ],
})

src/rules/__tests__/no-new-worker-with-w.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noNewWorkerWithWasmImport } from '../no-new-worker-with-wasm-import.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const SYNTHETIC_WASM_PKG = '@test/example-wasm'
const SYNTHETIC_WASM_PKG_NON_SCOPED = 'example-wasm'
const SYNTHETIC_WASM_SUBPATH = 'example-wasm/binding'

const newWorkerError = {
  messageId: 'forbiddenNewWorkerWithWasm' as const,
  data: {
    expected: 'Bun.spawn subprocess pool',
    actual: 'new Worker(filePath)',
    fix:
      'Run each worker in its own OS process (not in a thread of the parent) so each one has its own WASM heap and concurrent init cannot race. A subprocess-per-worker pool with a per-child crash handler (re-dispatch the in-flight work and spawn a replacement) is the standard shape.',
  },
}

ruleTester.run('no-new-worker-with-wasm-import', noNewWorkerWithWasmImport, {
  valid: [
    // No WASM import — new Worker is allowed
    {
      name: 'allows new Worker without WASM import',
      code: `
        const w = new Worker('./worker.js')
      `,
    },
    // Non-WASM import, new Worker in use — fine
    {
      name: 'allows new Worker when no WASM dep is imported',
      code: `
        import { foo } from 'some-lib'
        const w = new Worker('./worker.js')
      `,
    },
    // WASM-imported file but no new Worker — fine
    {
      name: 'allows WASM import with no new Worker',
      code: `
        import { fn } from '${SYNTHETIC_WASM_PKG}'
        const out = fn('payload')
      `,
    },
    // WASM-imported file using a subprocess-style alternative — correct path
    {
      name: 'allows subprocess-style pool with WASM import',
      code: `
        import { fn } from '${SYNTHETIC_WASM_PKG}'
        const child = startSubprocess(['run', './worker.ts'], { onCrash: handler })
      `,
    },
    // Non-WASM import that happens to contain the substring "wasm" — not matched
    {
      name: 'allows new Worker when import is not a WASM package (no -wasm suffix)',
      code: `
        import { config } from 'wasm-config-helper'
        const w = new Worker('./worker.js')
      `,
    },
    // Other NewExpression callees are fine
    {
      name: 'allows other NewExpression constructors with WASM import',
      code: `
        import { fn } from '${SYNTHETIC_WASM_PKG}'
        const m = new Map()
        const s = new Set()
        const e = new Error('oops')
      `,
    },
    // Non-scoped synthetic WASM dep with no new Worker
    {
      name: 'allows non-scoped WASM dep with no new Worker',
      code: `
        import { init } from '${SYNTHETIC_WASM_PKG_NON_SCOPED}'
        init()
      `,
    },
  ],
  invalid: [
    // Scoped synthetic WASM import + new Worker — fires
    {
      name: 'detects new Worker with scoped synthetic WASM import',
      code: `
        import { fn } from '${SYNTHETIC_WASM_PKG}'
        const w = new Worker('./worker.js')
      `,
      errors: [newWorkerError],
    },
    // Non-scoped synthetic WASM import + new Worker
    {
      name: 'detects new Worker with non-scoped synthetic WASM import',
      code: `
        import { init } from '${SYNTHETIC_WASM_PKG_NON_SCOPED}'
        const w = new Worker('./worker.ts')
      `,
      errors: [newWorkerError],
    },
    // Sub-path synthetic WASM import
    {
      name: 'detects new Worker with synthetic WASM sub-path import',
      code: `
        import { fn } from '${SYNTHETIC_WASM_SUBPATH}'
        const w = new Worker('./worker.js')
      `,
      errors: [newWorkerError],
    },
    // Default-imported synthetic WASM
    {
      name: 'detects new Worker with default-imported synthetic WASM',
      code: `
        import wasm from '${SYNTHETIC_WASM_PKG}'
        const w = new Worker('./worker.js')
      `,
      errors: [newWorkerError],
    },
    // Multiple new Worker usages with WASM dep
    {
      name: 'detects multiple new Worker usages with WASM import',
      code: `
        import { fn } from '${SYNTHETIC_WASM_PKG}'
        const w1 = new Worker('./a.js')
        const w2 = new Worker('./b.js')
      `,
      errors: [newWorkerError, newWorkerError],
    },
    // Custom expected + fix via options
    {
      name: 'honors custom expected and fix options',
      code: `
        import { fn } from '${SYNTHETIC_WASM_PKG}'
        const w = new Worker('./worker.js')
      `,
      options: [
        {
          expected: 'custom expected text',
          fix: 'custom fix text',
        },
      ],
      errors: [
        {
          messageId: 'forbiddenNewWorkerWithWasm',
          data: {
            expected: 'custom expected text',
            actual: 'new Worker(filePath)',
            fix: 'custom fix text',
          },
        },
      ],
    },
    // Custom wasmImportPatterns via options
    {
      name: 'honors custom wasmImportPatterns option',
      code: `
        import { something } from 'my-custom-package'
        const w = new Worker('./worker.js')
      `,
      options: [
        { wasmImportPatterns: ['my-custom-package'] },
      ],
      errors: [newWorkerError],
    },
  ],
})

src/rules/__tests__/no-inline-destructur.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'
import { noInlineDestructuredType } from '../no-inline-destructured-type.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const expectedMessage = 'Named type, utility type (Pick/Omit), or destructuring in function body'
const fixMessage = 'Extract to a named type, use Pick/Omit, or destructure in function body'

const inlineTypeError = (name: string) => ({
  messageId: 'noInlineDestructuredType' as const,
  data: {
    name,
    expected: expectedMessage,
    actual: 'Inline { prop: type } annotation',
    fix: fixMessage,
  },
})

ruleTester.run('no-inline-destructured-type', noInlineDestructuredType, {
  valid: [
    {
      name: 'Should_Pass_When_UsingNamedType',
      code: `function updateProfile({ name, age }: UserProfile) {}`,
    },
    {
      name: 'Should_Pass_When_UsingPickUtilityType',
      code: `function updateProfile({ name }: Pick<User, 'name'>) {}`,
    },
    {
      name: 'Should_Pass_When_UsingOmitUtilityType',
      code: `function updateProfile({ name }: Omit<User, 'age'>) {}`,
    },
    {
      name: 'Should_Pass_When_DestructuringInBody',
      code: `function updateProfile(user: User) { const { name } = user }`,
    },
    {
      name: 'Should_Pass_When_NoTypeAnnotation',
      code: `function fn({ x }) {}`,
    },
    {
      name: 'Should_Pass_When_NonDestructuredParamWithNamedType',
      code: `function fn(x: User) {}`,
    },
    {
      name: 'Should_Pass_When_ArrowFunctionWithNamedType',
      code: `const fn = ({ data }: DataType) => data`,
    },
    {
      name: 'Should_Pass_When_MethodWithNamedType',
      code: `const obj = { method({ id }: User) {} }`,
    },
    {
      name: 'Should_Pass_When_ClassMethodWithNamedType',
      code: `class Foo { method({ id }: User) {} }`,
    },
    {
      name: 'Should_Pass_When_UtilityTypeWithAllowUtilityTypesTrue',
      code: `function fn({ id }: Pick<User, 'id'>) {}`,
      options: [{ allowUtilityTypes: true }],
    },
    {
      name: 'Should_Pass_When_ConstructorParameterProperty',
      code: `class Foo { constructor(public name: string) {} }`,
    },
    {
      name: 'Should_Pass_When_DefaultParamWithNamedType',
      code: `function fn({ id }: User = { id: '1' }) {}`,
    },
    {
      name: 'Should_Pass_When_DefaultParamWithoutTypeAnnotation',
      code: `function fn({ id } = { id: '1' }) {}`,
    },
  ],
  invalid: [
    {
      name: 'Should_Report_When_FunctionDeclarationWithInlineType',
      code: `function updateProfile({ name, age }: { name: string; age: number }) {}`,
      errors: [inlineTypeError('updateProfile')],
    },
    {
      name: 'Should_Report_When_ArrowFunctionWithInlineType',
      code: `const handler = ({ data }: { data: number[] }) => data`,
      errors: [inlineTypeError('handler')],
    },
    {
      name: 'Should_Report_When_FunctionExpressionWithInlineType',
      code: `const fn = function ({ x }: { x: Date }) {}`,
      errors: [inlineTypeError('fn')],
    },
    {
      name: 'Should_Report_When_AnonymousDefaultExportWithInlineType',
      code: `export default function ({ x }: { x: string }) {}`,
      errors: [inlineTypeError('Anonymous function')],
    },
    {
      name: 'Should_Report_When_ClassMethodWithInlineType',
      code: `class Foo { method({ x }: { x: string }) {} }`,
      errors: [inlineTypeError('method')],
    },
    {
      name: 'Should_Report_When_ObjectMethodWithInlineType',
      code: `const obj = { handler({ x }: { x: string }) {} }`,
      errors: [inlineTypeError('handler')],
    },
    {
      name: 'Should_Report_When_MultipleInlineParams',
      code: `function fn({ a }: { a: string }, { b }: { b: number }) {}`,
      errors: [inlineTypeError('fn'), inlineTypeError('fn')],
    },
    {
      name: 'Should_Report_When_SinglePropertyInlineType',
      code: `function fn({ x }: { x: Date }) {}`,
      errors: [inlineTypeError('fn')],
    },
    {
      name: 'Should_Report_When_AnonymousArrowInCallback',
      code: `[1].map(({ x }: { x: number }) => x)`,
      errors: [inlineTypeError('Anonymous function')],
    },
    {
      name: 'Should_Report_When_NonDestructuredParamWithInlineType',
      code: `function fn(x: { id: string }) {}`,
      errors: [inlineTypeError('fn')],
    },
    {
      name: 'Should_Report_When_ArrowNonDestructuredParamWithInlineType',
      code: `const fn = (x: { id: string }) => x`,
      errors: [inlineTypeError('fn')],
    },
    {
      name: 'Should_Report_When_DefaultParamWithInlineType',
      code: `function fn({ id }: { id: string } = { id: '1' }) {}`,
      errors: [inlineTypeError('fn')],
    },
    {
      name: 'Should_Report_When_UtilityTypeWithAllowUtilityTypesFalse',
      code: `function fn({ id }: Pick<User, 'id'>) {}`,
