      errors: [inlineTypeError('fn')],
    },
  ],
})

src/rules/__tests__/no-native-settimeout.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noNativeSetTimeoutInEffect } from '../no-native-settimeout-in-effect.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const setTimeoutError = {
  messageId: 'forbiddenSetTimeout' as const,
  data: { expected: 'Effect.delay or Effect.sleep' },
}

ruleTester.run('no-native-settimeout-in-effect', noNativeSetTimeoutInEffect, {
  valid: [
    // No effect import — setTimeout is allowed
    {
      name: 'allows setTimeout without effect import',
      code: `
        setTimeout(() => {}, 1000)
      `,
    },
    // Effect imported but no setTimeout usage
    {
      name: 'allows code with effect import but no setTimeout usage',
      code: `
        import { Effect } from 'effect'
        const x = Effect.succeed(42)
      `,
    },
    // Non-effect import does not trigger
    {
      name: 'allows setTimeout with non-effect import',
      code: `
        import { something } from 'other-lib'
        setTimeout(() => {}, 1000)
      `,
    },
    // setInterval is not banned by this rule
    {
      name: 'allows setInterval with effect import',
      code: `
        import { Effect } from 'effect'
        setInterval(() => {}, 1000)
      `,
    },
    // Other function calls
    {
      name: 'allows other function calls with effect import',
      code: `
        import { Effect } from 'effect'
        console.log('hello')
        Math.random()
      `,
    },
    // Variable alias that is NOT setTimeout — must not false-positive
    {
      name: 'allows non-setTimeout variable alias called in effect context',
      code: `
        import { Effect } from 'effect'
        const doStuff = () => {}
        doStuff()
      `,
    },
  ],
  invalid: [
    // Direct setTimeout
    {
      name: 'detects setTimeout() with effect import',
      code: `
        import { Effect } from 'effect'
        setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // effect/ sub-path import
    {
      name: 'detects setTimeout with effect/ sub-path import',
      code: `
        import { Duration } from 'effect/Duration'
        setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // @effect/ scoped import
    {
      name: 'detects setTimeout with @effect/ scoped import',
      code: `
        import { Schema } from '@effect/schema'
        setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // globalThis.setTimeout
    {
      name: 'detects globalThis.setTimeout() with effect import',
      code: `
        import { Effect } from 'effect'
        globalThis.setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // window.setTimeout
    {
      name: 'detects window.setTimeout() with effect import',
      code: `
        import { Effect } from 'effect'
        window.setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // self.setTimeout
    {
      name: 'detects self.setTimeout() with effect import',
      code: `
        import { Effect } from 'effect'
        self.setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // Bracket access: globalThis['setTimeout']
    {
      name: 'detects globalThis["setTimeout"]() with effect import',
      code: `
        import { Effect } from 'effect'
        globalThis['setTimeout'](() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // Bracket access: window['setTimeout']
    {
      name: 'detects window["setTimeout"]() with effect import',
      code: `
        import { Effect } from 'effect'
        window['setTimeout'](() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // Aliased setTimeout (assignment is not a call, so only alias call reports)
    {
      name: 'detects aliased setTimeout with effect import',
      code: `
        import { Effect } from 'effect'
        const myTimeout = setTimeout
        myTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // Aliased from globalThis member
    {
      name: 'detects alias from globalThis.setTimeout',
      code: `
        import { Effect } from 'effect'
        const st = globalThis.setTimeout
        st(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
    // Multiple setTimeout usages
    {
      name: 'detects multiple setTimeout usages',
      code: `
        import { Effect } from 'effect'
        setTimeout(() => {}, 1000)
        setTimeout(() => {}, 2000)
      `,
      errors: [setTimeoutError, setTimeoutError],
    },
    // Namespace import triggers
    {
      name: 'detects setTimeout with namespace import from effect',
      code: `
        import * as E from 'effect'
        setTimeout(() => {}, 1000)
      `,
      errors: [setTimeoutError],
    },
  ],
})

src/rules/__tests__/no-direct-tag-access.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noDirectTagAccess } from '../no-direct-tag-access.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const defaultError = (name: string) => [
  {
    messageId: 'forbidden' as const,
    data: {
      name,
      expected:
        'Effect Match API or type guards — Match.tag(value, { Tag1: () => ... }), Result.isSuccess/Result.isFailure, Either.isLeft/Either.isRight, Exit.isSuccess/Exit.isFailure, Option.isSome/Option.isNone',
      actual: 'direct _tag property access',
      fix:
        'Replace obj._tag === "X" with Match.tag(obj, { X: () => ... }) or use Result.isSuccess/isFailure, Either.isLeft/isRight, Exit.isSuccess/isFailure, Option.isSome/isNone as appropriate',
    },
  },
]

ruleTester.run('no-direct-tag-access', noDirectTagAccess, {
  valid: [
    // Non-_tag properties
    {
      name: 'allows access to non-_tag properties',
      code: `const x = obj.name`,
    },
    {
      name: 'allows access to tag without underscore',
      code: `const x = obj.tag`,
    },
    {
      name: 'allows computed property with non-_tag value',
      code: `const x = obj["type"]`,
    },
    // Non-_tag property in comparison — isTagProperty guard
    {
      name: 'allows non-_tag property in comparison',
      code: `if (result.type === 'Success') {}`,
    },
    // Allow list
    {
      name: 'allows _tag comparison when in allow list',
      code: `if (result._tag === 'Foo') {}`,
      options: [{ allow: ['result._tag'] }],
    },
    // Pure value access — not in comparison or switch
    {
      name: 'allows _tag access as value assignment',
      code: `const x = result._tag`,
    },
    {
      name: 'allows _tag access on member expression as value',
      code: `const x = foo.bar._tag`,
    },
    {
      name: 'allows _tag access via bracket notation as value',
      code: `const x = result["_tag"]`,
    },
    {
      name: 'allows _tag in test assertion',
      code: `expect(result._tag).toBe('Right')`,
    },
    {
      name: 'allows _tag as span attribute value',
      code: `const attrs = { errorType: error._tag }`,
    },
    {
      name: 'allows _tag passed as function argument',
      code: `log(error._tag)`,
    },
    {
      name: 'allows _tag in template literal',
      code: 'const msg = `error: ${error._tag}`',
    },
    {
      name: 'allows _tag in array map',
      code: `const tags = items.map(e => e._tag)`,
    },
  ],
  invalid: [
    // === comparison
    {
      name: 'reports _tag in strict equality comparison',
      code: `if (result._tag === "Success") {}`,
      errors: defaultError('result._tag'),
    },
    // !== comparison
    {
      name: 'reports _tag in strict inequality comparison',
      code: `if (result._tag !== "Failure") {}`,
      errors: defaultError('result._tag'),
    },
    // switch statement
    {
      name: 'reports _tag in switch discriminant',
      code: `switch (result._tag) { case "Left": break }`,
      errors: defaultError('result._tag'),
    },
    // Nested member expression in comparison
    {
      name: 'reports _tag on nested member in comparison',
      code: `if (foo.bar._tag === "Baz") {}`,
      errors: defaultError('foo.bar._tag'),
    },
    // Bracket notation in comparison
    {
      name: 'reports _tag bracket notation in comparison',
      code: `if (result["_tag"] === "Left") {}`,
      errors: defaultError('result._tag'),
    },
    // Custom messages
    {
      name: 'uses custom expected and fix messages',
      code: `if (value._tag === 'X') {}`,
      options: [{ expected: 'Custom expected', fix: 'Custom fix' }],
      errors: [
        {
          messageId: 'forbidden' as const,
          data: {
            name: 'value._tag',
            expected: 'Custom expected',
            actual: 'direct _tag property access',
            fix: 'Custom fix',
          },
        },
      ],
    },
    // Allow list doesn't cover this identifier
    {
      name: 'reports _tag comparison not in allow list',
      code: `if (other._tag === 'X') {}`,
      options: [{ allow: ['result._tag'] }],
      errors: defaultError('other._tag'),
    },
    // Ternary with comparison
    {
      name: 'reports _tag in ternary comparison',
      code: `const x = result._tag === 'Left' ? 'bad' : 'good'`,
      errors: defaultError('result._tag'),
    },
    // Boolean expression with &&
    {
      name: 'reports _tag comparison in logical expression',
      code: `const ok = isValid && result._tag === 'Right'`,
      errors: defaultError('result._tag'),
    },
    // switch with member expression
    {
      name: 'reports _tag switch on nested member',
      code: `switch (error._tag) { case "NotFound": break; case "Timeout": break }`,
      errors: defaultError('error._tag'),
    },
  ],
})

src/rules/__tests__/no-io-boundary-tests.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noIoBoundaryTests } from '../no-io-boundary-tests.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const IN_SOURCE = 'if (import.meta.vitest) { const { it } = await import("@effect/vitest") }'

const inSourceError = [{ messageId: 'inSourceTest' as const }]
const testFileError = [{ messageId: 'testFile' as const }]

ruleTester.run('no-io-boundary-tests', noIoBoundaryTests, {
  valid: [
    {
      name: 'allows in-source vitest in a worker (executor) file',
      code: IN_SOURCE,
      filename: 'src/supervision/pg-monitor/workers/pg-monitor.worker.ts',
    },
    {
      name: 'allows in-source vitest in a schema file',
      code: IN_SOURCE,
      filename: 'src/x/pg-stats.schema.ts',
    },
    {
      name: 'allows in-source vitest in a plain executor file',
      code: IN_SOURCE,
      filename: 'src/x/issue-token.executor.ts',
    },
    {
      name: 'allows an acl with no in-source test block',
      code: 'export const decode = transformOrFail(A, B, {})',
      filename: 'src/x/decode.acl.ts',
    },
    {
      name: 'allows a non-vitest if whose object is not import.meta',
      code: 'if (config.vitest) { run() }',
      filename: 'src/x/decode.acl.ts',
    },
    {
      name: 'allows import.meta access to a property other than vitest',
      code: 'if (import.meta.env) { run() }',
      filename: 'src/x/decode.acl.ts',
    },
    {
      name: 'allows a non-test call in an acl test-named file',
      code: 'helper("x")',
      filename: 'src/x/decode.acl.test.ts',
    },
    {
      name: 'allows a member call whose base is not a test fn',
      code: 'obj.describe("x")',
      filename: 'src/x/decode.acl.test.ts',
    },
    {
      name: 'allows describe in a non-io test file',
      code: 'describe("x", () => {})',
      filename: 'src/x/decode.test.ts',
    },
    {
      name: 'allows an acl-suffixed source name that does not end at the ts extension',
      code: IN_SOURCE,
      filename: 'src/x/decode.acl.ts.map',
    },
    {
      name: 'allows an acl test name that does not end at the ts extension',
      code: 'describe("x", () => {})',
      filename: 'src/x/decode.acl.test.ts.map',
    },
  ],
  invalid: [
    {
      name: 'flags in-source vitest in an acl file',
      code: IN_SOURCE,
      filename: 'src/x/decode.acl.ts',
      errors: inSourceError,
    },
    {
      name: 'flags in-source vitest in a store file',
      code: IN_SOURCE,
      filename: 'src/x/orders.store.ts',
      errors: inSourceError,
    },
    {
      name: 'flags in-source vitest in an adapter file',
      code: IN_SOURCE,
      filename: 'src/x/fcm.adapter.ts',
      errors: inSourceError,
    },
    {
      name: 'flags in-source vitest in a handler file',
      code: IN_SOURCE,
      filename: 'src/x/token.handler.ts',
      errors: inSourceError,
    },
    {
      name: 'flags in-source vitest in a .acl.tsx file',
      code: IN_SOURCE,
      filename: 'src/x/decode.acl.tsx',
      errors: inSourceError,
    },
    {
      name: 'flags in-source vitest in a .acl.mts file',
      code: IN_SOURCE,
      filename: 'src/x/decode.acl.mts',
      errors: inSourceError,
    },
    {
      name: 'flags a describe call in a .acl.test.mts file',
      code: 'describe("x", () => {})',
      filename: 'src/x/decode.acl.test.mts',
      errors: testFileError,
    },
    {
      name: 'flags a describe call in an acl test file',
      code: 'describe("x", () => {})',
      filename: 'src/x/decode.acl.test.ts',
      errors: testFileError,
    },
    {
      name: 'flags an it call in a store spec file',
      code: 'it("x", () => {})',
      filename: 'src/x/orders.store.spec.ts',
      errors: testFileError,
    },
    {
      name: 'flags a test call in an adapter test file',
      code: 'test("x", () => {})',
      filename: 'src/x/fcm.adapter.test.ts',
      errors: testFileError,
    },
    {
      name: 'flags it.prop (member callee) in a handler test file',
      code: 'it.prop("x", [], () => true)',
      filename: 'src/x/token.handler.test.ts',
      errors: testFileError,
    },
    {
      name: 'flags it.each (call-chain callee) in an acl test file',
      code: 'it.each([1])("x", () => {})',
      filename: 'src/x/decode.acl.test.ts',
      errors: testFileError,
    },
    {
      name: 'flags a test call passed as an argument (parent call, not its callee)',
      code: 'wrap(it("x", () => {}))',
      filename: 'src/x/decode.acl.test.ts',
      errors: testFileError,
    },
  ],
})

src/rules/__tests__/no-new-promise-in-ef.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noNewPromiseInEffect } from '../no-new-promise-in-effect.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const newPromiseError = {
  messageId: 'forbiddenNewPromise' as const,
  data: {
    expected: 'Effect.async or Promise.withResolvers',
    actual: 'new Promise(executor)',
    fix: 'Replace with Effect.async for Effect pipelines, or Promise.withResolvers for native Promise composition',
  },
}

ruleTester.run('no-new-promise-in-effect', noNewPromiseInEffect, {
  valid: [
    // No effect import — new Promise is allowed
    {
      name: 'allows new Promise without effect import',
      code: `
        new Promise((resolve, reject) => { resolve(42) })
      `,
    },
    // Effect imported but no new Promise usage
    {
      name: 'allows code with effect import but no new Promise',
      code: `
        import { Effect } from 'effect'
        const x = Effect.succeed(42)
      `,
    },
    // Non-effect import does not trigger
    {
      name: 'allows new Promise with non-effect import',
      code: `
        import { something } from 'other-lib'
        new Promise((resolve) => { resolve(1) })
      `,
    },
    // Promise.resolve / Promise.all are not constructors
    {
      name: 'allows Promise.resolve with effect import',
      code: `
        import { Effect } from 'effect'
        Promise.resolve(42)
        Promise.all([])
      `,
    },
    // new Promise() with no arguments (bare constructor)
    {
      name: 'allows new Promise() with no arguments and effect import',
      code: `
        import { Effect } from 'effect'
        new Promise()
      `,
    },
    // new Promise with non-function argument
    {
      name: 'allows new Promise with non-function argument',
      code: `
        import { Effect } from 'effect'
        new Promise(someVariable)
      `,
    },
    // Other constructors are fine
    {
      name: 'allows other constructors with effect import',
      code: `
        import { Effect } from 'effect'
        new Map()
        new Set()
        new Error('oops')
      `,
    },
  ],
  invalid: [
    // Arrow function executor
    {
      name: 'detects new Promise with arrow executor and effect import',
      code: `
        import { Effect } from 'effect'
        new Promise((resolve, reject) => { resolve(42) })
      `,
      errors: [newPromiseError],
    },
    // Function expression executor
    {
      name: 'detects new Promise with function expression executor',
      code: `
        import { Effect } from 'effect'
        new Promise(function(resolve, reject) { resolve(42) })
      `,
      errors: [newPromiseError],
    },
    // effect/ sub-path import
    {
      name: 'detects new Promise with effect/ sub-path import',
      code: `
        import { Duration } from 'effect/Duration'
        new Promise((resolve) => { resolve(1) })
      `,
      errors: [newPromiseError],
    },
    // @effect/ scoped import
    {
      name: 'detects new Promise with @effect/ scoped import',
      code: `
        import { Schema } from '@effect/schema'
        new Promise((resolve) => { resolve(1) })
      `,
      errors: [newPromiseError],
    },
    // Namespace import triggers
    {
      name: 'detects new Promise with namespace import from effect',
      code: `
        import * as E from 'effect'
        new Promise((resolve) => { resolve(1) })
      `,
      errors: [newPromiseError],
    },
    // Resolve-only arrow
    {
      name: 'detects new Promise with single-param arrow',
      code: `
        import { Effect } from 'effect'
        new Promise((resolve) => resolve(42))
      `,
      errors: [newPromiseError],
    },
    // Multiple new Promise usages
    {
      name: 'detects multiple new Promise usages',
      code: `
        import { Effect } from 'effect'
        new Promise((resolve) => resolve(1))
        new Promise((resolve, reject) => { reject(new Error('fail')) })
      `,
      errors: [newPromiseError, newPromiseError],
    },
    // Async executor (still banned)
    {
      name: 'detects new Promise with async arrow executor',
      code: `
        import { Effect } from 'effect'
        new Promise(async (resolve) => { resolve(await fetch('/api')) })
      `,
      errors: [newPromiseError],
    },
  ],
})

src/rules/__tests__/no-date-now-in-effec.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { noDateNowInEffect } from '../no-date-now-in-effect.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const dateNowError = {
  messageId: 'forbiddenDateNow' as const,
  data: { expected: 'yield* Clock.currentTimeMillis (Clock from effect)' },
}

const prod = (code: string) => ({ code, filename: 'src/feature.ts' })

ruleTester.run('no-date-now-in-effect', noDateNowInEffect, {
  valid: [
    {
      name: 'allows Date.now() in a file that does not import effect',
      ...prod(`
        const now = Date.now()
        const later = Date.now() + 1000
      `),
    },
    {
      name: 'allows a now() call on a non-Date object',
      ...prod(`
        import { Effect } from 'effect'
        const t = performance.now()
      `),
    },
    {
      name: 'allows Clock.currentTimeMillis',
      ...prod(`
        import { Clock, Effect } from 'effect'
        const program = Effect.gen(function*() {
          const now = yield* Clock.currentTimeMillis
          return now
        })
      `),
    },
    {
      name: 'allows a different Date member',
      ...prod(`
        import { Effect } from 'effect'
        const program = Effect.gen(function*() {
          return new Date(0).toISOString()
        })
      `),
    },
    {
      name: 'skips test scaffolding files where clock-as-salt is legitimate',
      code: `
        import { Effect } from 'effect'
        const layer = Effect.gen(function*() {
          const salt = Date.now()
          return salt
        })
      `,
      filename: 'packages/lib/statement-store/test/runtime/ppn-runtime.ts',
    },
  ],
  invalid: [
    {
      name: 'detects Date.now() directly in an Effect.gen body',
      ...prod(`
        import { Effect } from 'effect'
        const program = Effect.gen(function*() {
          const now = Date.now()
          return now
        })
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects Date.now() lifted via Effect.sync — not an escape hatch',
      ...prod(`
        import { Effect } from 'effect'
        const now = Effect.sync(() => Date.now())
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects Date.now() in a plain handler arrow within an effect-importing file',
      ...prod(`
        import { Effect } from 'effect'
        const makeRoute = Effect.gen(function*() {
          const isRateLimited = (ip: string) => {
            const now = Date.now()
            return now > 0
          }
          return isRateLimited
        })
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects Date.now() with effect/ sub-path import',
      ...prod(`
        import { Duration } from 'effect/Duration'
        const t = Date.now()
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects Date.now() with @effect/ scoped import',
      ...prod(`
        import { Schema } from '@effect/schema'
        const t = Date.now()
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects bracket-access Date["now"]()',
      ...prod(`
        import { Effect } from 'effect'
        const t = Date['now']()
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects Math.floor(Date.now() / 1000)',
      ...prod(`
        import { Effect } from 'effect'
        const program = Effect.gen(function*() {
          return Math.floor(Date.now() / 1000)
        })
      `),
      errors: [dateNowError],
    },
    {
      name: 'detects multiple Date.now() usages',
      ...prod(`
        import { Effect } from 'effect'
        const a = Date.now()
        const b = Date.now()
      `),
      errors: [dateNowError, dateNowError],
    },
    {
      name: 'detects Date.now() with namespace import from effect',
      ...prod(`
        import * as E from 'effect'
        const t = Date.now()
      `),
      errors: [dateNowError],
    },
  ],
})

