src/rules/__tests__/policy-no-domain-imp.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { policyNoDomainImports } from '../policy-no-domain-imports.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

const POLICY_FILE = 'src/infrastructure/rate-limiter.policy.ts'

const domainImportError = (source: string, suffix: string) => [
  { messageId: 'domainImport' as const, data: { source, suffix } },
]

const importsBannedSuffix = (suffix: string) => ({
  name: `flags import of a .${suffix} module from a policy`,
  code: `import { thing } from './neighbour.${suffix}.js'`,
  filename: POLICY_FILE,
  errors: domainImportError(`./neighbour.${suffix}.js`, suffix),
})

ruleTester.run('policy-no-domain-imports', policyNoDomainImports, {
  valid: [
    {
      name: 'allows effect imports in a policy',
      code: `import { Effect, Schedule } from 'effect'`,
      filename: POLICY_FILE,
    },
    {
      name: 'allows @effect scoped imports in a policy',
      code: `import { HttpClient } from '@effect/platform'`,
      filename: POLICY_FILE,
    },
    {
      name: 'allows importing a schema sibling for key types',
      code: `import { SubmissionKey } from './submission-key.schema.js'`,
      filename: POLICY_FILE,
    },
    {
      name: 'allows importing another policy',
      code: `import { withBulkhead } from './bulkhead.policy.js'`,
      filename: POLICY_FILE,
    },
    {
      name: 'ignores a store import outside a policy file',
      code: `import { save } from './order.store.js'`,
      filename: 'src/infrastructure/order.executor.ts',
    },
    {
      name: 'ignores a workflow import in an unsuffixed file',
      code: `import { decide } from './order.workflow.js'`,
      filename: 'src/infrastructure/helper.ts',
    },
  ],
  invalid: [
    importsBannedSuffix('workflow'),
    importsBannedSuffix('executor'),
    importsBannedSuffix('store'),
    importsBannedSuffix('acl'),
    importsBannedSuffix('handler'),
    importsBannedSuffix('middleware'),
    importsBannedSuffix('adapter'),
    importsBannedSuffix('service'),
    importsBannedSuffix('shell'),
    importsBannedSuffix('use-case'),
    importsBannedSuffix('daemon'),
    importsBannedSuffix('repository'),
    {
      name: 'flags an import from a nested behavioural path',
      code: `import { decide } from '#root/features/order/place-order.workflow.js'`,
      filename: POLICY_FILE,
      errors: domainImportError('#root/features/order/place-order.workflow.js', 'workflow'),
    },
    {
      name: 'flags a named re-export from a store',
      code: `export { save } from './order.store.js'`,
      filename: POLICY_FILE,
      errors: domainImportError('./order.store.js', 'store'),
    },
    {
      name: 'flags an export-all from a workflow',
      code: `export * from './order.workflow.js'`,
      filename: POLICY_FILE,
      errors: domainImportError('./order.workflow.js', 'workflow'),
    },
    {
      name: 'flags a dynamic import of an executor',
      code: `import('./order.executor.js')`,
      filename: POLICY_FILE,
      errors: domainImportError('./order.executor.js', 'executor'),
    },
  ],
})

src/rules/__tests__/ban-error-string.tes.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'

import { banErrorString } from '../ban-error-string.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

ruleTester.run('ban-error-string', banErrorString, {
  valid: [
    {
      name: 'Should_Pass_When_IsStringCallRejectsNonStringPatterns',
      code: `
        class F { #String(v) { return v }; make(error) { throw new Error(this.#String(error)) } }
        new Error('message')
        new Error(String())
        new Error(Number(error))
        new Error(globalThis.Number(error))
        new Error(globalThis['String'](error))
        new Error(((v) => v)(error))
        new ((() => Error)())('msg')
      `,
    },
    {
      name: 'Should_Pass_When_NonErrorLikeNames',
      code: `
        String(someValue)
        someValue.toString()
        \`\${someValue}\`
      `,
    },
    {
      name: 'Should_Pass_When_ToStringCallBoundaries',
      code: `
        const m = 'toString'
        error.toString(16)
        error[m]()
        error.valueOf()
      `,
    },
    {
      name: 'Should_Pass_When_TemplateLiteralBoundaries',
      code: `
        \`Error: \${error}\`
        \`\${error} happened\`
        \`\${error}\${error}\`
      `,
    },
  ],
  invalid: [
    {
      name: 'Should_Report_When_NewErrorUsesStringIdentifierCallee',
      code: 'throw new Error(String(e))',
      errors: [
        {
          messageId: 'forbidden',
          data: {
            pattern: 'new Error(String(error))',
            expected: "new Error('message', { cause: error })",
            actual: 'new Error(String(e))',
            fix: 'replace String(error) with an explicit message and { cause: error }',
          },
          suggestions: [
            {
              messageId: 'useCause',
              data: { pattern: 'String(e)', replacement: "'Error occurred', { cause: e }" },
              output: "throw new Error('Error occurred', { cause: e })",
            },
          ],
        },
      ],
    },
    {
      name: 'Should_Report_When_NewErrorUsesMemberExpressionPaths',
      code: 'throw new Errors.NetworkError(globalThis.String(cause))',
      errors: [
        {
          messageId: 'forbidden',
          suggestions: [
            {
              messageId: 'useCause',
              output: "throw new Errors.NetworkError('Error occurred', { cause: cause })",
            },
          ],
        },
      ],
    },
    {
      name: 'Should_Report_When_StandaloneStringWrapsErrorLikeNames',
      code: `
        String(error)
        new Result(String(error))
      `,
      errors: [
        { messageId: 'standaloneStringWrap', data: { name: 'error' } },
        { messageId: 'standaloneStringWrap', data: { name: 'error' } },
      ],
    },
    {
      name: 'Should_Report_When_ToStringOrTemplateLiteralCoercesError',
      code: `
        error.toString()
        \`\${error}\`
      `,
      errors: [
        { messageId: 'toStringWrap', data: { name: 'error' } },
        { messageId: 'templateLiteralWrap', data: { name: 'error' } },
      ],
    },
  ],
})

src/rules/__tests__/no-bodyless-status-a.source:
import { RuleTester } from 'oxlint/plugins-dev'
import * as vitest from 'vitest'
import { noBodylessStatusAssertion } from '../no-bodyless-status-assertion.js'

RuleTester.it = vitest.it
RuleTester.itOnly = vitest.it.only
RuleTester.describe = vitest.describe

const ruleTester = new RuleTester({
  languageOptions: {
    parserOptions: {
      lang: 'ts',
    },
  },
})

ruleTester.run('no-bodyless-status-assertion', noBodylessStatusAssertion, {
  valid: [
    {
      name: 'Should_Allow_When_CheckResponseWithBodyIsUsed',
      code: `await checkResponseWithBody(response, 200)`,
    },
    {
      name: 'Should_Allow_When_StatusComparedToStringLiteral',
      code: `expect(finalData.status).toBe('ASSIGNED')`,
    },
    {
      name: 'Should_Allow_When_StatusComparedToVariable',
      code: `expect(response.status).toBe(expectedStatus)`,
    },
    {
      name: 'Should_Allow_When_NonStatusPropertyComparedToNumber',
      code: `expect(response.length).toBe(200)`,
    },
    {
      name: 'Should_Allow_When_NonExpectCallWrapsStatusMember',
      code: `assert(response.status).toBe(200)`,
    },
    {
      name: 'Should_Allow_When_ComputedStatusMemberComparedToNumber',
      code: `expect(response['status']).toBe(200)`,
    },
    {
      name: 'Should_Allow_When_MatcherIsNotEquality',
      code: `expect(response.status).toBeGreaterThan(200)`,
    },
  ],
  invalid: [
    {
      name: 'Should_Flag_When_CheckResponseCalled',
      code: `checkResponse(response, 200)`,
      errors: [{ messageId: 'preferCheckResponseWithBody' }],
    },
    {
      name: 'Should_Flag_When_ExpectStatusToBeNumber',
      code: `expect(response.status).toBe(200)`,
      errors: [{ messageId: 'bodylessStatusAssertion' }],
    },
    {
      name: 'Should_Flag_When_ExpectStatusToBeNonOkNumber',
      code: `expect(response.status).toBe(402)`,
      errors: [{ messageId: 'bodylessStatusAssertion' }],
    },
    {
      name: 'Should_Flag_When_ExpectStatusToEqualNumber',
      code: `expect(response.status).toEqual(404)`,
      errors: [{ messageId: 'bodylessStatusAssertion' }],
    },
    {
      name: 'Should_Flag_When_ExpectStatusToStrictEqualNumber',
      code: `expect(response.status).toStrictEqual(204)`,
      errors: [{ messageId: 'bodylessStatusAssertion' }],
    },
  ],
})
